// Some portions generated by Codex
const assert = require('node:assert/strict');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const { spawnSync } = require('node:child_process');
const test = require('node:test');

for (const platform of ['Linux', 'Darwin']) {
    for (const browser of ['chromium', 'firefox', 'webkit', '']) {
        test(`${platform} ${browser || 'all browsers'} provisions the required display`, () => {
            const temporary = fs.mkdtempSync(path.join(os.tmpdir(), 'rdf4j-display-test-'));
            const trace = path.join(temporary, 'commands.txt');
            const executable = (name, source) => {
                fs.writeFileSync(path.join(temporary, name), `#!/bin/bash\n${source}\n`, { mode: 0o755 });
            };
            executable('uname', 'printf "%s\\n" "$E2E_TEST_PLATFORM"');
            executable('mvn', 'exit 0');
            executable('curl', 'exit 0');
            executable('npx', 'printf "playwright %s\\n" "$*" >> "$E2E_DISPLAY_TRACE"');
            executable('xvfb-run', 'printf "xvfb\\n" >> "$E2E_DISPLAY_TRACE"\n'
                + 'while [ "$#" -gt 0 ]; do\n'
                + '  case "$1" in -a) shift;; -s) shift 2;; *) break;; esac\n'
                + 'done\nexec "$@"');
            const outcome = spawnSync('/bin/bash', [path.resolve(__dirname, '../run.sh'), 'spring-boot'], {
                env: { ...process.env, PATH: `${temporary}${path.delimiter}${process.env.PATH}`,
                    E2E_TEST_PLATFORM: platform, E2E_DISPLAY_TRACE: trace, E2E_BROWSER: browser,
                    E2E_SKIP_PLAYWRIGHT_INSTALL: 'true', E2E_DATA_DIR: path.join(temporary, 'data') },
                encoding: 'utf8', timeout: 20000
            });
            assert.equal(outcome.status, 0, outcome.stdout + outcome.stderr);
            const commands = fs.readFileSync(trace, 'utf8').trim().split('\n');
            const needsDisplay = platform === 'Linux' && browser !== 'chromium';
            assert.equal(commands.includes('xvfb'), needsDisplay, commands.join('\n'));
            assert.equal(commands.at(-1), `playwright playwright test${browser ? ` --project=${browser}` : ''}`);
        });
    }
}
